import{z as s,x as p,o as r,c as A,q as t,j as i,D as e,d as o,s as B,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"IPO 抑价作为理论","description":"","frontmatter":{"title":"IPO 抑价作为理论","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ipo-underpricing-theory.md","filePath":"econ/ipo-underpricing-theory.md","lastUpdated":1791413859000}'),d={name:"econ/ipo-underpricing-theory.md"};function c(h,a,m,u,D,f){const n=p("Mermaid");return r(),A("div",null,[a[2]||(a[2]=t('<h1 id="ipo-抑价作为理论" tabindex="-1">IPO 抑价作为理论 <a class="header-anchor" href="#ipo-抑价作为理论" aria-label="Permalink to &quot;IPO 抑价作为理论&quot;">​</a></h1><div class="epigraph"><p>新股必须平均折价，否则不知情的投资者总是买到知情者不买的那些券。</p><footer>—— Rock, Why New Issues are Underpriced, Journal of Financial Economics 1986；对照 Welch, Journal of Finance 1989</footer></div><p><a href="/econ/convertible-security">上一课</a>（可转债）。公司金融已经把成熟企业的现金切成派息、留存与债务纪律。本课缺口换成进入公众市场的那一次切片：为什么发行价系统低于首日交易价——作为<strong>均衡理论</strong>，不是作为发行统计。不写抑价均值表，不把长期弱势当成本文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>优序说股权信息敏感、柠檬折价重，成熟企业尽量不发。IPO 却必须发，而且常见的不是「按公平价格刚好售罄」，而是故意留下首日收益。若把这读成承销商无能或发行人喜欢送钱，没有经济学。缺口是：在谁知情、谁分配到股份的结构下，折价是参与约束还是信号。</p><p>Rock（1986）给出赢家诅咒：知情者只认购被低估的发行，不知情者在被高估的发行里占比过高。不知情者若按平均质量参与，期望收益为负，会退出。要让他们留下，平均发行必须折价。Welch（1989）给出另一条：高类型用抑价发信号，以便后续增发时被识别。两条都是理论；发行日历与抑价百分数留给别处。</p><p><span class="marginnote">抑价指发行价低于首日收盘（或首日交易价）。它不是「IPO 长期回报低」。长期弱势是另一组事实，Loughran 与 Ritter 的对照句在边界，本课不把两套事实焊成一个模型。</span></p><p><span class="marginnote">「赢家诅咒」翻译成大白话：你赢了申购，本身就是坏消息——因为对手比你更不想要它。数字实例：好券发 8 元、值 12 元，知情者涌入抢购，不知情者按比例每人只分到 10 股；差券同样发 8 元、只值 6 元，没人抢，不知情者足额买到。两组加权后不知情者平均亏钱，于是退出申购池。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>赢家诅咒。设部分投资者观测到发行的真实价值，部分不观测。配售按申购分配：被低估的券超额申购，不知情者分到的少；被高估的券知情者退出，不知情者分到的多。不知情者的条件期望因此差于无条件期望。发行价必须低到使不知情者的条件期望覆盖参与，于是无条件的平均首日收益为正。</p><p>信号。高价值发行人比低价值发行人更愿意承受当期折价，若折价能换来后市较高的再发行价格或较好的市场声誉。分离均衡里，抑价是 Spence 式的有成本行动，对象是类型，不是配售。与<a href="/econ/pecking-order">优序</a>的方向对照：优序尽量避免发股泄漏；IPO 信号则选择泄漏，因为必须公开上市。</p>',11)),(r(),i(l,null,{default:e(()=>[B(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INFO%5B%22%E9%83%A8%E5%88%86%E6%8A%95%E8%B5%84%E8%80%85%E7%9F%A5%E6%83%85%22%5D%20--%3E%20WC%5B%22%E8%B5%A2%E5%AE%B6%E8%AF%85%E5%92%92%3A%20%E4%B8%8D%E7%9F%A5%E6%83%85%E8%80%85%E9%85%8D%E5%88%B0%E5%B7%AE%E5%88%B8%22%5D%0A%20%20WC%20--%3E%20UP%5B%22%E5%B9%B3%E5%9D%87%E6%8A%98%E4%BB%B7%E4%BB%A5%E6%BB%A1%E8%B6%B3%E5%8F%82%E4%B8%8E%22%5D%0A%20%20TYPE%5B%22%E5%8F%91%E8%A1%8C%E4%BA%BA%E7%B1%BB%E5%9E%8B%E7%A7%81%E6%9C%89%22%5D%20--%3E%20SIG%5B%22Welch%3A%20%E6%8A%91%E4%BB%B7%E5%8F%91%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20SIG%20--%3E%20SEO%5B%22%E5%90%8E%E7%BB%AD%E5%8F%91%E8%A1%8C%E8%A2%AB%E8%AF%86%E5%88%AB%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"两种理论对「谁获益」预测不同：诅咒补偿的是不知情买家；信号支付的是类型揭示。本课并列，不裁判哪一篇回归赢。簿记建档改变的是配售规则，因而改变诅咒的强度，并不自动把发行价变成二级市场的均衡报价。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"信号的成本结构像「烧钱立信」：低类型装不起。举例：若高类型折价 5000 万能换来后市增发多募 1 亿元，而低类型后市照样破发、增发只能多募 2000 万，那么同样一笔折价只有高类型划算——折价于是成了低类型模仿不起的可置信声明。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[o("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"机制是配售与信息，不是「市场喜欢便宜货」。若股份按意愿分配且信息对称，发行价可以贴近事后交易价，抑价不是必需。信息不对称一旦与固定价格、配给相结合，参与约束就落在信息最少的那一组人身上，折价是让他们留在池子里的费用。拍卖与簿记可以改变分配规则，从而改变诅咒的严重程度；那是机制设计，不是把 Rock 取消。",-1)),(r(),i(l,null,{default:e(()=>[B(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20GOOD%5B%22%E5%8F%91%E8%A1%8C%E8%A2%AB%E4%BD%8E%E4%BC%B0%22%5D%20--%3E%20RUSH%5B%22%E7%9F%A5%E6%83%85%E8%80%85%E8%B6%85%E9%A2%9D%E7%94%B3%E8%B4%AD%22%5D%0A%20%20RUSH%20--%3E%20FEW%5B%22%E4%B8%8D%E7%9F%A5%E6%83%85%E8%80%85%E6%8C%89%E6%AF%94%E4%BE%8B%E5%88%86%E5%BE%97%E5%B0%91%22%5D%0A%20%20BAD%5B%22%E5%8F%91%E8%A1%8C%E8%A2%AB%E9%AB%98%E4%BC%B0%22%5D%20--%3E%20EXIT%5B%22%E7%9F%A5%E6%83%85%E8%80%85%E9%80%80%E5%87%BA%22%5D%0A%20%20EXIT%20--%3E%20MANY%5B%22%E4%B8%8D%E7%9F%A5%E6%83%85%E8%80%85%E9%85%8D%E5%88%B0%E8%B6%B3%E9%A2%9D%22%5D%0A%20%20FEW%20--%3E%20NEG%5B%22%E4%B8%8D%E7%9F%A5%E6%83%85%E8%80%85%E6%9D%A1%E4%BB%B6%E6%9C%9F%E6%9C%9B%E4%B8%BA%E8%B4%9F%22%5D%0A%20%20MANY%20--%3E%20NEG%0A%20%20NEG%20--%3E%20CUT%5B%22%E5%8F%91%E8%A1%8C%E4%BB%B7%E4%B8%8B%E8%B0%83%2C%20%E8%A1%A5%E9%BD%90%E5%8F%82%E4%B8%8E%E8%B4%B9%E7%94%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p>与半强式 <a href="/econ/emh">EMH</a> 的接缝：首日收盘把公开发行的信息写入价格，并不否证有效。抑价发生在<strong>发行价</strong>这一非连续交易的定价环节，发行价不是二级市场的均衡报价。强式失败（有人有私人信息）正是诅咒的前提。公司金融与有效市场在这里同用一层信息，不打架。</p><p><span class="marginnote">常见误区：把抑价读成承销商算错价。实际上定价方完全清楚首日大概率会涨——折价是故意付给不知情投资者的「参与费」。这一步若省掉，下一次发行时申购池里只剩知情者，认购不足，发行直接失败，这就是「为什么重要」。</span></p><h3 id="一句对照-不写发行统计" tabindex="-1">一句对照，不写发行统计 <a class="header-anchor" href="#一句对照-不写发行统计" aria-label="Permalink to &quot;一句对照，不写发行统计&quot;">​</a></h3><p>Loughran 与 Ritter 问过：发行人为什么不因为「桌上留钱」而愤怒。那是对抑价<strong>作为事实</strong>的行为与代理补充——经理更关心上市成功与后市，而不是最后一美元的发行收入。本课只用这一句标明：理论解释的是均衡折价为何存在，不解释某年代、某板块的抑价有多高。数字与日历不是本栏对象。</p><p><span class="marginnote">承销商信誉、诉讼风险、流动性补偿，都是文献里的其他候选。主干只保留诅咒与信号两条，以免 IPO 课变成综述清单。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把首日收益的截面异象、热销市场、长期回报写成定理。那些是量化或实证公司金融；本课停在参与约束与信号。也不要把抑价当成对 MM 的否证：MM 假设公平价格发行；IPO 正是公平价格假设失败的场合。</p><p>下一课离开发行折价，问上市之后投票权与现金流权是否还绑在一起：<a href="/econ/control-rights">控制权</a>。</p><p>后课默认：IPO 平均抑价可以是赢家诅咒下的参与约束，或类型信号。不是发行统计课。二级市场把公开信息写入价格，与半强式兼容。</p><p>发行价不是限价簿上的均衡报价。不要在这里预支微观结构。</p><p>桌上留钱是代理与行为的对照句，不是 Rock 的替代证明。</p><p>首日收益是发行价与二级价格的差，不是对半强式的否证。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>股权在优序里信息敏感；IPO 必须发，折价有均衡理由。</li><li>Rock：不知情者的赢家诅咒要求平均抑价。</li><li>Welch：抑价可以是为后续发行支付的信号成本。</li><li>出处：Rock, <em>JFE</em> 1986；Welch, <em>Journal of Finance</em> 1989；Loughran and Ritter 一句对照。</li></ul>',14))])}const P=s(d,[["render",c]]);export{g as __pageData,P as default};
